import{z as s,x as p,o as E,c as A,q as n,j as l,D as e,d as i,s as o,S as B,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"钌覆盖层","description":"","frontmatter":{"title":"钌覆盖层","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/ruthenium-capping.md","filePath":"litho/ruthenium-capping.md","lastUpdated":1791413859000}'),d={name:"litho/ruthenium-capping.md"};function h(u,a,m,c,D,R){const r=p("Mermaid");return E(),A("div",null,[a[2]||(a[2]=n('<h1 id="钌覆盖层" tabindex="-1">钌覆盖层 <a class="header-anchor" href="#钌覆盖层" aria-label="Permalink to &quot;钌覆盖层&quot;">​</a></h1><div class="epigraph"><p>Mo/Si 怕氧、怕氢、怕碳。几纳米钌当帽：保住布拉格周期，自己尽量少吃带内反射率，还要允许氢刻锡。</p><footer>—— 据 Bajt 等对 Ru 帽层；Bakshi 多层与表面化学</footer></div><p><a href="/litho/euv-phase-shift-mask">上一课</a>无论二元还是相移，工作面都是多层顶。缺口是这层顶在真空、氢和 EUV 下怎么活：量产公开的覆盖层是钌（Ru）。黑边要把场外多层弄黑，留给<a href="/litho/black-border">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>硅顶层在空气或残余水里氧化，周期膨胀、对比下降；氢自由基可以刻碳也可以攻击错误的帽；锡若落到无帽界面，清洗会连硅一起伤。需要一层薄帽：13.5 nm 吸收尽量小、连续、抗氧、在氢等离子体中相对惰，并且不把 MSFR 抬起来。钌是公开选中的折中，不是「最不吸收的元素」。</p><p><span class="marginnote">术语翻译：帽层（capping layer）就是给多层膜最顶上加的一层「保护漆」——几纳米厚，既要替下面的 Mo/Si 挡住氧、氢这些攻击，自己在 13.5 nm 又不能太挡光。</span></p><p>缺口是帽层合同，不是再讲 Mo/Si 周期公式。掩模空白和投影镜都用帽，但掩模还要在上面刻吸收体、修缺陷、装 pellicle，帽的针孔就是相位坑。</p><p><span class="marginnote">帽层厚度是反射率与保护的折中，公开量级是数纳米。太厚，峰值 \\(R\\) 掉；太薄，针孔和扩散。不要把某张 TEM 照片的厚度当全球规格。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>沉积：在多层完成后加 Ru，有时带超薄阻挡以免 Ru 与 Si 互扩散。掩模厂再在帽上沉积吸收体并图形化，刻蚀必须停在帽上或可控地微侵，不能把布拉格堆挖穿——除非故意做黑边。氢清洗假设帽在，收集镜课已经用过这个假设。</p><p>计量：峰值 \\(R\\)、氧化前后差、氢暴露后的起泡与应力、缺陷密度。针孔在光化检验上表现为相位缺陷，打印阈值随照明变。</p><h3 id="大气暴露是掩模帽的额外税" tabindex="-1">大气暴露是掩模帽的额外税 <a class="header-anchor" href="#大气暴露是掩模帽的额外税" aria-label="Permalink to &quot;大气暴露是掩模帽的额外税&quot;">​</a></h3><p>投影镜几乎不离开真空；掩模要进出盒、检验机和大气。钌减缓氧化，但不能无限次暴露。帽上的自然氧化层改一点 n、k 和应力，反复进出后 \\(R\\) 和相位指纹会走。存储与搬运的惰性气氛是帽层合同的一部分，不是设施附录。</p>',13)),(E(),l(B,null,{default:e(()=>[o(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20ML%5B%22Mo%2FSi%20%E5%91%A8%E6%9C%9F%22%5D%20--%3E%20RU%5B%22Ru%20%E5%B8%BD%22%5D%0A%20%20RU%20--%3E%20PROT%5B%22%E6%8A%97%E6%B0%A7%20%2F%20%E6%8A%97%E6%B0%A2%E7%AA%97%E5%8F%A3%22%5D%0A%20%20RU%20--%3E%20R%5B%22%E7%95%A5%E7%89%BA%E7%89%B2%E5%B8%A6%E5%86%85%20R%22%5D%0A%20%20ABS%5B%22%E5%90%B8%E6%94%B6%E4%BD%93%22%5D%20--%3E%20RU%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[i("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"Ru 在 13.5 nm 的光学常数允许薄层仍有可接受透过（作为帽，不是作为吸收体）。它减缓氧向硅的扩散，并提供氢刻锡时的化学终点：SnH₄ 走，Ru 尽量留。Bajt 等的多层帽层工作表明，帽同时改应力和轻微相移——吸收体 + 帽 + 多层是同一块电磁物。氢植入起泡若发生在帽–多层界面，MSFR 和局部相位一起坏，氢等离子体课的不可逆项在掩模上同样成立。",-1)),(E(),l(B,null,{default:e(()=>[o(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20O2%5B%22%E6%AE%8B%E4%BD%99%E6%B0%A7%E4%B8%8E%E6%B0%B4%E6%B1%BD%22%5D%20--%3E%20SI%5B%22%E9%A1%B6%E5%B1%82%E7%A1%85%E8%A2%AB%E6%B0%A7%E5%8C%96%22%5D%0A%20%20SI%20--%3E%20EXP%5B%22%E5%91%A8%E6%9C%9F%E8%86%A8%E8%83%80%20%E5%AF%B9%E6%AF%94%E4%B8%8B%E9%99%8D%22%5D%0A%20%20RUCAP%5B%22%E9%92%8C%E5%B8%BD%E6%8B%A6%E6%88%AA%22%5D%20--%3E%20SLOW%5B%22%E6%B0%A7%E5%90%91%E7%A1%85%E7%9A%84%E6%89%A9%E6%95%A3%E8%A2%AB%E5%87%8F%E7%BC%93%22%5D%0A%20%20HPL%5B%22%E6%B0%A2%E7%AD%89%E7%A6%BB%E5%AD%90%E4%BD%93%E6%B8%85%E6%B4%97%22%5D%20--%3E%20SNH%5B%22%E9%94%A1%E5%8F%98%E6%88%90%20SnH%E2%82%84%20%E8%A2%AB%E5%B8%A6%E8%B5%B0%22%5D%0A%20%20SNH%20--%3E%20KEEP%5B%22Ru%20%E5%B0%BD%E9%87%8F%E7%95%99%E5%9C%A8%E5%8E%9F%E5%9C%B0%22%5D%0A%20%20HIMP%5B%22%E6%B0%A2%E6%A4%8D%E5%85%A5%22%5D%20--%3E%20BUB%5B%22%E5%B8%BD-%E5%A4%9A%E5%B1%82%E7%95%8C%E9%9D%A2%E8%B5%B7%E6%B3%A1%3A%20%E4%B8%8D%E5%8F%AF%E9%80%86%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">数字实例：投影镜有六面（0.33 NA）到八面（High-NA）多层反射镜，单面峰值反射率约 0.7，整机透过约 \\(0.7^{6}\\approx 12\\%\\) 到 \\(0.7^{8}\\approx 5.8\\%\\)。任何一面镜子因帽层氧化把 \\(R\\) 再拖低几个百分点，到达硅片的光子就再少一截，源功率的账立刻变难看。</span></p><p><span class="marginnote">掩模帽与投影镜帽配方不必相同：掩模还要兼容吸收体刻蚀和大气暴露；投影镜几乎不离开真空。不要写成一种 Ru 膜打天下。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写场边缘如何把多层蚀穿做成黑边，下一课才写。不重写收集镜清洗流量。帽的针孔按相位缺陷管，按吸收体缺陷管会漏检。出处：Bajt Ru capping；Bakshi；Madey 表面化学；氢等离子体课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>钌帽保护 Mo/Si 对抗氧和氢，并给刻蚀一个可停的表面，代价是一点 \\(R\\) 和潜在针孔。</li><li>吸收体、相移层和缺陷都坐在帽上，帽是掩模电磁的一部分。</li><li>下一课：场与场之间那圈「不该反光」的黑边。</li><li>出处：Bajt；Bakshi；ASML/SEMATECH 帽层公开讨论。</li></ul><p><span class="marginnote">常见误区：把帽层针孔当「普通遮挡缺陷」去检查。针孔处多层裸露、相位突变，印出来是相位缺陷——按吸收体缺陷的阈值去管，会漏检。</span></p>',7))])}const _=s(d,[["render",h]]);export{f as __pageData,_ as default};
